-- Amarix Store core schema v1
-- Applied to Supabase project pvuobngrybygohendwaz on 2026-10-31.
create extension if not exists pgcrypto with schema extensions;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,full_name text,role text not null default 'customer' check(role in ('admin','staff','customer')),created_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),slug text not null unique,name_ar text not null,name_en text,kind text not null check(kind in ('smm','numbers','games','apps','ai','custom')),sort_order int not null default 0,is_active boolean not null default true,created_at timestamptz not null default now());
create table public.providers(id uuid primary key default gen_random_uuid(),code text not null unique,name text not null,kind text not null check(kind in ('smm','numbers','topup','stock','custom')),base_url text,secret_name text,config jsonb not null default '{}'::jsonb,is_active boolean not null default false,last_test_at timestamptz,last_sync_at timestamptz,balance numeric(18,6),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(),category_id uuid references public.categories(id) on delete set null,slug text not null unique,name_ar text not null,name_en text,description text,image_url text,fulfillment_type text not null default 'manual' check(fulfillment_type in ('smm','number','topup','stock','manual')),input_schema jsonb not null default '[]'::jsonb,price numeric(18,6) not null default 0 check(price>=0),cost numeric(18,6) not null default 0 check(cost>=0),currency text not null default 'USD',sort_order int not null default 0,is_active boolean not null default false,is_featured boolean not null default false,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.provider_services(id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.providers(id) on delete cascade,external_service_id text not null,name text not null,category_hint text,service_type text,min_quantity bigint,max_quantity bigint,rate numeric(18,6),raw jsonb not null default '{}'::jsonb,is_active boolean not null default true,synced_at timestamptz not null default now(),unique(provider_id,external_service_id));
create table public.product_provider_routes(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,provider_service_id uuid not null references public.provider_services(id) on delete cascade,priority int not null default 100,markup_percent numeric(9,4) not null default 0,is_active boolean not null default true,unique(product_id,provider_service_id));
create table public.wallets(user_id uuid not null references auth.users(id) on delete cascade,currency text not null default 'USD',balance numeric(18,6) not null default 0 check(balance>=0),updated_at timestamptz not null default now(),primary key(user_id,currency));
create table public.wallet_ledger(id bigint generated always as identity primary key,user_id uuid not null references auth.users(id) on delete restrict,currency text not null default 'USD',amount numeric(18,6) not null check(amount<>0),balance_after numeric(18,6) not null check(balance_after>=0),entry_type text not null check(entry_type in ('topup','purchase','refund','adjustment')),reference text,note text,created_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(),order_number bigint generated always as identity unique,user_id uuid references auth.users(id) on delete set null,product_id uuid references public.products(id) on delete set null,product_snapshot jsonb not null default '{}'::jsonb,customer_inputs jsonb not null default '{}'::jsonb,quantity numeric(18,4) not null default 1 check(quantity>0),total numeric(18,6) not null check(total>=0),currency text not null default 'USD',status text not null default 'pending' check(status in ('pending','processing','completed','partial','failed','cancelled')),payment_status text not null default 'pending' check(payment_status in ('pending','review','paid','refunded','failed')),provider_order_id text,idempotency_key text unique,delivery jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.payment_topups(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,amount numeric(18,6) not null check(amount>0),currency text not null default 'USD',method text not null check(method in ('syriatel_cash','sham_cash','usdt_bep20','binance_pay','manual')),proof_path text,reference text,status text not null default 'pending' check(status in ('pending','approved','rejected')),reviewed_by uuid references auth.users(id) on delete set null,reviewed_at timestamptz,created_at timestamptz not null default now());
create table public.api_call_logs(id bigint generated always as identity primary key,provider_id uuid references public.providers(id) on delete set null,operation text not null,success boolean not null default false,http_status int,duration_ms int,error_message text,created_at timestamptz not null default now());
create table public.staff_permissions(user_id uuid not null references auth.users(id) on delete cascade,permission text not null,granted_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),primary key(user_id,permission));
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin'); $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,email,role) values(new.id,new.email,case when lower(coalesce(new.email,''))='amarov0077@gmail.com' then 'admin' else 'customer' end) on conflict(id) do update set email=excluded.email; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
insert into public.profiles(id,email,role) select id,email,'admin' from auth.users where lower(email)='amarov0077@gmail.com' on conflict(id) do update set email=excluded.email,role='admin';
insert into public.categories(slug,name_ar,name_en,kind,sort_order) values ('smm','خدمات الرشق','Social Media Services','smm',10),('numbers','أرقام التفعيل','Activation Numbers','numbers',20),('games','شحن الألعاب','Game Top-ups','games',30),('apps','التطبيقات والاشتراكات','Apps & Subscriptions','apps',40),('ai','الذكاء الاصطناعي','AI Subscriptions','ai',50);
create index products_category_active_sort_idx on public.products(category_id,is_active,sort_order);
create index orders_user_created_idx on public.orders(user_id,created_at desc);
create index ledger_user_created_idx on public.wallet_ledger(user_id,created_at desc);
create index topups_status_created_idx on public.payment_topups(status,created_at desc);
alter table public.profiles enable row level security; alter table public.categories enable row level security; alter table public.providers enable row level security; alter table public.products enable row level security; alter table public.provider_services enable row level security; alter table public.product_provider_routes enable row level security; alter table public.wallets enable row level security; alter table public.wallet_ledger enable row level security; alter table public.orders enable row level security; alter table public.payment_topups enable row level security; alter table public.api_call_logs enable row level security; alter table public.staff_permissions enable row level security;
create policy profiles_read_self_or_admin on public.profiles for select to authenticated using(id=(select auth.uid()) or (select public.is_admin()));
create policy categories_public_read on public.categories for select to anon,authenticated using(is_active or (select public.is_admin()));
create policy providers_admin_all on public.providers for all to authenticated using((select public.is_admin())) with check((select public.is_admin()));
create policy products_public_read on public.products for select to anon,authenticated using(is_active or (select public.is_admin()));
create policy provider_services_admin_all on public.provider_services for all to authenticated using((select public.is_admin())) with check((select public.is_admin()));
create policy routes_admin_all on public.product_provider_routes for all to authenticated using((select public.is_admin())) with check((select public.is_admin()));
create policy wallets_read_self_or_admin on public.wallets for select to authenticated using(user_id=(select auth.uid()) or (select public.is_admin()));
create policy ledger_read_self_or_admin on public.wallet_ledger for select to authenticated using(user_id=(select auth.uid()) or (select public.is_admin()));
create policy orders_read_self_or_admin on public.orders for select to authenticated using(user_id=(select auth.uid()) or (select public.is_admin()));
create policy topups_read_self_or_admin on public.payment_topups for select to authenticated using(user_id=(select auth.uid()) or (select public.is_admin()));
create policy topups_admin_update on public.payment_topups for update to authenticated using((select public.is_admin())) with check((select public.is_admin()));
create policy api_logs_admin_read on public.api_call_logs for select to authenticated using((select public.is_admin()));
create policy staff_permissions_admin_all on public.staff_permissions for all to authenticated using((select public.is_admin())) with check((select public.is_admin()));
grant select on public.categories,public.products to anon,authenticated;
grant select on public.profiles,public.wallets,public.wallet_ledger,public.orders,public.payment_topups to authenticated;
grant select,insert,update,delete on public.providers,public.categories,public.products,public.provider_services,public.product_provider_routes,public.staff_permissions to authenticated;
grant select on public.api_call_logs to authenticated;
grant usage,select on all sequences in schema public to authenticated;
grant execute on function public.is_admin() to authenticated;
